float round(float x) {
  return (x >= 0.0) ? floor(x + 0.5) : ceil(x - 0.5);
}

// Decode a weighted sum (9*center + neighbors)
void decode(float sum, out float center, out float neighbors)
{
  sum = round(sum);

  // the center decoding here is WRONG
  // it should be:
  //center = float(sum - 9. >= 0.);
  // but the corrected version is a bit
  // boring in the current rule case
  // so I'm leaving the wrong one here
  center = round(sum / 9.);
  neighbors = mod(sum, 9.);
}

// Six relatively prime weights.
// The modulus is also prime.
float hash(
    float n_x, float n_y, float n_z,
    float c_x, float c_y, float c_z,
    float rotation)
{
  float w0=19.;
  float w1=17.;
  float w2=13.;
  float w3=11.;

  for(int i=0;i<3;i++){

      if(float(i)<rotation){

          float t=w0;
          w0=w1;
          w1=w2;
          w2=w3;
          w3=t;
      }
  }

  float m = 23.0;
  float sum = 0.0;

  sum += mod(n_x,        m);
  sum += mod(n_y * w0,   m);
  sum += mod(n_z * w1,   m);
  sum += mod(c_x * 9.0,  m);
  sum += mod(c_y * w2,   m);
  sum += mod(c_z * w3,   m);

  return mod(sum, m);
}

bool inSet(
    float x,
    float a,float b,float c,float d,
    float e,float f,float g,float h)
{
    return
        x==a||x==b||x==c||x==d||
        x==e||x==f||x==g||x==h;
}

bool birthRule(float phase) {
    return inSet(
        phase,
         3., -1., -1., -1.,
        -1., -1., -1., -1.
    );
}

bool surviveRule(float phase) {
    return inSet(
        phase,
        11., 12., -1., -1.,
        -1., -1., -1., -1.
    );
}

vec3 activation(float r, float g, float b)
{
  float rc, rn;
  float gc, gn;
  float bc, bn;
  decode(r, rc, rn);
  decode(g, gc, gn);
  decode(b, bc, bn);

  //---------------------
  // Phase information
  //---------------------
  float phaseR = hash(rn,gn,bn,rc,gc,bc, 0.);
  float phaseG = hash(gn,bn,rn,gc,bc,rc, 0.);
  float phaseB = hash(bn,rn,gn,bc,rc,gc, 0.);

  bool birthR = birthRule(phaseR);
  bool surviveR = surviveRule(phaseR);

  bool birthG = birthRule(phaseG);
  bool surviveG = surviveRule(phaseG);

  bool birthB = birthRule(phaseB);
  bool surviveB = surviveRule(phaseB);

  bool r_alive = rc == 1.;
  bool g_alive = gc == 1.;
  bool b_alive = bc == 1.;

    bool nextR =
    (r_alive && surviveR) ||
    (!r_alive && birthR);

  bool nextG =
    (g_alive && surviveG) ||
    (!g_alive && birthG);

  bool nextB =
    (b_alive && surviveB) ||
    (!b_alive && birthB);

  return vec3(
    nextR ? 1.0 : 0.0,
    nextG ? 1.0 : 0.0,
    nextB ? 1.0 : 0.0
  );
}
